export interface Quote {
  number: number;
  flag: string;
  chinese: string;
  pinyin: string;
  source: string;
  japanese: string;
  english?: string;
}

export const QUOTES: Quote[] = [
  { number: 1, flag: "🇨🇳", chinese: "授人以鱼不如授人以渔", pinyin: "shòu rén yǐ yú bù rú shòu rén yǐ yú", source: "老子", japanese: "人に魚を与えるより、魚の釣り方を教える方がよい。知識やスキルの習得の重要性を説く言葉。", english: "Give a man a fish and you feed him for a day; teach him to fish and you feed him for a lifetime. This proverb highlights the importance of gaining lasting knowledge and skills." },
  { number: 2, flag: "🇨🇳", chinese: "学如登山", pinyin: "xué rú dēng shān", source: "中国のことわざ", japanese: "学ぶことは山に登るようなものだ。険しい道のりだが、頂上からの景色は素晴らしい。", english: "Learning is like climbing a mountain — the path is steep, but the view from the summit makes every step worthwhile." },
  { number: 3, flag: "🇨🇳", chinese: "念念不忘", pinyin: "niàn niàn bù wàng", source: "中国のことわざ", japanese: "常に心に留めて忘れないこと。学習したことを反復し、記憶に定着させる重要性を示す。", english: "Keep it constantly in mind and never forget. Repetition and review are the keys to retaining what you have studied." },
  { number: 4, flag: "🇨🇳", chinese: "三人行，必有我师", pinyin: "sān rén xíng ， bì yǒu wǒ shī", source: "孔子", japanese: "三人で行動すれば、必ずその中に自分の師となる人がいる。誰からでも学ぶべき点があるという教え。", english: "When three people walk together, one is always a teacher. There is something to learn from everyone you meet." },
  { number: 5, flag: "🇨🇳", chinese: "师傅领进门，修行在个人", pinyin: "shī fù lǐng jìn mén ， xiū xíng zài gè rén", source: "中国のことわざ", japanese: "師匠は門まで導いてくれるが、そこから先の修行は自分次第である。自発的な学習の重要性を説く。", english: "A master can open the door, but practice is up to you alone. Self-driven study is what ultimately leads to mastery." },
  { number: 6, flag: "🇨🇳", chinese: "活到老，学到老", pinyin: "huó dào lǎo ， xué dào lǎo", source: "中国のことわざ", japanese: "老いるまで生き、老いるまで学ぶ。生涯学習の精神を表す言葉。", english: "Live until old age, learn until old age. Embrace lifelong learning — there is always more to discover." },
  { number: 7, flag: "🇨🇳", chinese: "严师出高徒", pinyin: "yán shī chū gāo tú", source: "中国のことわざ", japanese: "厳しい師匠からは優れた弟子が育つ。厳格な指導と学習の重要性を示す。", english: "A strict teacher produces talented students. Rigorous study and high standards lead to remarkable achievement." },
  { number: 8, flag: "🇨🇳", chinese: "读万卷书不如行万里路", pinyin: "dú wàn juàn shū bù rú xíng wàn lǐ lù", source: "董其昌（明代の書画家）", japanese: "万巻の書を読むより、万里の道を歩く方がよい。実践的な経験や見聞を広めることの重要性を説く。", english: "Reading ten thousand books is not as good as traveling ten thousand miles. Real-world experience brings language to life." },
  { number: 9, flag: "🇨🇳", chinese: "学无止境", pinyin: "xué wú zhǐ jìng", source: "中国のことわざ", japanese: "学問に終わりはない。常に新しい知識を求め続けるべきだという教え。", english: "There is no limit to learning. Knowledge is boundless — always seek to know more." },
  { number: 10, flag: "🇨🇳", chinese: "学然后知不足", pinyin: "xué rán hòu zhī bù zú", source: "『礼記』", japanese: "学んで初めて自分の知識の不足を知る。学習を進めることで謙虚になり、さらなる探求心を生む。", english: "Only through study do we discover how much we do not know. Learning cultivates humility and deeper curiosity." },
  { number: 11, flag: "🇨🇳", chinese: "教学相长", pinyin: "jiào xué xiāng zhǎng", source: "『礼記』", japanese: "教えることと学ぶことは互いに成長を促す。人に教えることで自分自身の理解も深まる。", english: "Teaching and learning grow together. Explaining what you know to others deepens your own understanding." },
  { number: 12, flag: "🇨🇳", chinese: "温故而知新", pinyin: "wēn gù ér zhī xīn", source: "孔子", japanese: "過去の知識や経験を復習し、そこから新しい知識や見解を得ること。", english: "Review the past to understand the new. Revisiting what you have already learned reveals fresh insights." },
  { number: 13, flag: "🇨🇳", chinese: "玉不琢，不成器", pinyin: "yù bù zuó ， bù chéng qì", source: "『礼記』", japanese: "玉も磨かなければ器にならない。人も教育や学習を通じて初めて立派な人物になる。", english: "Jade without polishing cannot become a vessel. Education and practice are what shape raw talent into true ability." },
  { number: 14, flag: "🇨🇳", chinese: "学如逆水行舟，不进则退", pinyin: "xué rú nì shuǐ xíng zhōu ， bù jìn zé tuì", source: "中国のことわざ", japanese: "学ぶことは流れに逆らって船を進めるようなもので、前進しなければ後退してしまう。継続的な学習の必要性を説く。", english: "Learning is like rowing upstream — stop moving forward and you drift back. Consistent effort is essential." },
  { number: 15, flag: "🇨🇳", chinese: "书山有路勤为径，学海无涯苦作舟", pinyin: "shū shān yǒu lù qín wèi jìng ， xué hǎi wú yá kǔ zuò zhōu", source: "韓愈（唐代の文学者）", japanese: "書物の山に道はあるが勤勉さがその小道であり、学問の海に果てはないが苦労がその舟である。", english: "The mountain of books has a path: diligence is that path. The sea of learning has no shore: perseverance is the vessel." },
  { number: 16, flag: "🇨🇳", chinese: "知之者不如好之者，好之者不如乐之者", pinyin: "zhī zhī zhě bù rú hǎo zhī zhě ， hǎo zhī zhě bù rú lè zhī zhě", source: "孔子", japanese: "これを知る者はこれを好む者に如かず、これを好む者はこれを楽しむ者に如かず。学習を楽しむことが最高の上達法。", english: "Knowing is not as good as loving it; loving is not as good as delighting in it. The highest form of learning is finding joy in the process." },
  { number: 17, flag: "🇨🇳", chinese: "学而不思则罔，思而不学则殆", pinyin: "xué ér bù sī zé wǎng ， sī ér bù xué zé dài", source: "孔子", japanese: "学んで思わざれば則ち罔し、思うて学ばざれば則ち殆し。知識と思考の両方が不可欠である。", english: "Learning without thinking is wasted effort; thinking without learning is dangerous. Knowledge and reflection must go hand in hand." },
  { number: 18, flag: "🇨🇳", chinese: "吾十有五而志于学", pinyin: "wú shí yǒu wǔ ér zhì yú xué", source: "孔子", japanese: "十五にして学に志す。若い頃から学問に目標を持ち、努力を始めること。", english: "At fifteen, I set my heart on study. Setting clear learning goals from an early age is the foundation of achievement." },
  { number: 19, flag: "🇨🇳", chinese: "三十而立", pinyin: "sān shí ér lì", source: "孔子", japanese: "三十にして立つ。学問によって自立し、自分の考えを確立すること。", english: "At thirty, I stood firm. Through study and practice, we establish our own principles and stand on our own." },
  { number: 20, flag: "🇨🇳", chinese: "四十而不惑", pinyin: "sì shí ér bù huò", source: "孔子", japanese: "四十にして惑わず。道理を理解し、迷うことなく学習や人生を進めること。", english: "At forty, I had no doubts. Deep understanding through learning leads to clarity and confidence in one's path." },
  { number: 21, flag: "🇨🇳", chinese: "五十而知天命", pinyin: "wǔ shí ér zhī tiān mìng", source: "孔子", japanese: "五十にして天命を知る。自分の使命や役割を理解し、それに沿って学び生きること。", english: "At fifty, I understood heaven's will. Learning eventually reveals our purpose — what we are meant to do and be." },
  { number: 22, flag: "🇨🇳", chinese: "有教无类", pinyin: "yǒu jiào wú lèi", source: "孔子", japanese: "教えありて類なし。教育は誰にでも平等に与えられるべきであり、学ぶ意欲があれば誰でも成長できる。", english: "Teach all, without distinction. Education should be equally available to anyone with the will to learn." },
  { number: 23, flag: "🇨🇳", chinese: "知之为知之，不知为不知，是知也", pinyin: "zhī zhī wéi zhī zhī ， bù zhī wèi bù zhī ， shì zhī yě", source: "孔子", japanese: "知っていることは知っているとし、知らないことは知らないとする。それが本当の知るということだ。", english: "Know what you know, and know what you do not know — that is true knowledge. Intellectual honesty is the foundation of real learning." },
  { number: 24, flag: "🇨🇳", chinese: "三军可夺帅也，匹夫不可夺志也", pinyin: "sān jūn kě duó shuài yě ， pǐ fū bù kě duó zhì yě", source: "孔子", japanese: "大軍の将軍は奪うことができるが、一人の男の志は奪うことができない。学習に対する強い信念を持つこと。", english: "You can rob an army of its commander, but you cannot rob a person of their will. A strong commitment to learning cannot be taken away." },
  { number: 25, flag: "🇨🇳", chinese: "过而不改，是谓过矣", pinyin: "guò ér bù gǎi ， shì wèi guò yǐ", source: "孔子", japanese: "過ちて改めざる、これを過ちという。学習での間違いを素直に認め、修正することの重要性。", english: "A mistake not corrected is a true mistake. Acknowledge errors honestly and use them as stepping stones in your studies." },
  { number: 26, flag: "🇨🇳", chinese: "欲速则不达", pinyin: "yù sù zé bù dá", source: "孔子", japanese: "急がば回れ。焦って結果を求めるとかえって失敗する。基礎から着実に学ぶことの重要性。", english: "Haste makes waste. Rushing toward results undermines the careful study that leads to true mastery." },
  { number: 27, flag: "🇨🇳", chinese: "过犹不及", pinyin: "guò yóu bù jí", source: "孔子", japanese: "過ぎたるは及ばざるが如し。学習においても無理をしすぎず、適度なペースを保つこと。", english: "Too much is as bad as too little. In language study, a balanced and sustainable pace outperforms frantic overwork." },
  { number: 28, flag: "🇨🇳", chinese: "君子和而不同，小人同而不和", pinyin: "jūn zǐ hé ér bù tóng ， xiǎo rén tóng ér bù hé", source: "孔子", japanese: "優れた人は協調するが同調はしない。自分の主体性を持ちながら、他者から学ぶ姿勢。", english: "A gentleman seeks harmony but not uniformity. Maintain your own principles while learning from every person you encounter." },
  { number: 29, flag: "🇨🇳", chinese: "有朋自远方来 不亦乐乎", pinyin: "yǒu péng zì yuǎn fāng lái  bù yì lè hū", source: "孔子", japanese: "友が遠方から訪ねてくるのは楽しいことだ。共に学ぶ仲間との交流の喜びを表す。", english: "Is it not a joy when friends come from afar? Learning alongside others brings inspiration and shared motivation." },
  { number: 30, flag: "🇨🇳", chinese: "譬如为山，未成一篑，止吾止也", pinyin: "pì rú wèi shān ， wèi chéng yī kuì ， zhǐ wú zhǐ yě", source: "孔子", japanese: "山を作るようなもので、最後の一杯の土を盛らずにやめるのは自分の責任だ。学習を途中で投げ出さないことの重要性。", english: "Stopping just before the last basketful of earth is your own choice. Never abandon your studies just before the breakthrough." },
  { number: 31, flag: "🇨🇳", chinese: "内省不疚，夫何忧何惧", pinyin: "nèi xǐng bù jiù ， fū hé yōu hé jù", source: "孔子", japanese: "心にやましいところがなければ、何を憂い恐れることがあろうか。自信を持って学習の成果を発揮すること。", english: "If your conscience is clear, what is there to worry or fear? Approach learning with confidence, knowing you have done your best." },
  { number: 32, flag: "🇨🇳", chinese: "巧言令色，鲜矣仁", pinyin: "qiǎo yán lìng sè ， xiān yǐ rén", source: "孔子", japanese: "言葉巧みで表情を取り繕う者には、思いやりが少ない。表面的な知識だけでなく、本質を深く学ぶことの重要性。", english: "Fine words and an ingratiating manner rarely indicate genuine character. Seek depth of understanding, not superficial knowledge." },
  { number: 33, flag: "🇨🇳", chinese: "千里之行，始于足下", pinyin: "qiān lǐ zhī xíng ， shǐ yú zú xià", source: "老子", japanese: "千里の道も一歩から。膨大な単語学習も、まずは一つの単語を覚えることから始まる。", english: "A journey of a thousand miles begins with a single step. Every vocabulary word you learn today is one step toward fluency." },
  { number: 34, flag: "🇨🇳", chinese: "大智若愚", pinyin: "dà zhì ruò yú", source: "老子", japanese: "大智は愚なるが如し。本当に賢い人は知識をひけらかさない。深く学び、内面を磨くこと。", english: "Great wisdom looks like foolishness. Truly knowledgeable people study quietly and deeply, without showing off." },
  { number: 35, flag: "🇨🇳", chinese: "知人者智，自知者明", pinyin: "zhī rén zhě zhì ， zì zhī zhě míng", source: "老子", japanese: "他者を知る者は智恵があり、自分を知る者は賢明である。自分の学習の弱点を把握することの重要性。", english: "Knowing others is wisdom; knowing yourself is enlightenment. Identify your own weaknesses in learning and work on them." },
  { number: 36, flag: "🇨🇳", chinese: "青出于蓝而胜于蓝", pinyin: "qīng chū yú lán ér shèng yú lán", source: "荀子", japanese: "青は藍より出でて藍より青し。弟子が師匠を超えること。学習を重ねて教えられた以上の実力を身につけること。", english: "Blue dye comes from the indigo plant yet surpasses it in color. A dedicated student can surpass even the teacher." },
  { number: 37, flag: "🇨🇳", chinese: "聪明出于勤奋，天才在于积累", pinyin: "cōng míng chū yú qín fèn ， tiān cái zài yú jī lěi", source: "華羅庚（中国の数学者）", japanese: "賢さは勤勉から生まれ、天才は積み重ねから生まれる。日々の単語学習や努力の蓄積が重要であるという教え。", english: "Intelligence comes from diligence; talent is built through accumulation. Daily study and steady effort outweigh raw ability." },
  { number: 38, flag: "🇨🇳", chinese: "必须敢于正视，这才可望敢想、敢说、敢做、敢当", pinyin: "bì xū gǎn yú zhèng shì ， zhè cái kě wàng gǎn xiǎng 、 gǎn shuō 、 gǎn zuò 、 gǎn dāng", source: "魯迅（近代中国の文学者）", japanese: "物事を直視する勇気があってこそ、考え、語り、行動し、責任を持つことができる。学習における積極的な姿勢を促す。", english: "One must dare to confront reality — only then can one dare to think, speak, act, and take responsibility. Face your learning challenges head-on." },
  { number: 39, flag: "🇨🇳", chinese: "事实胜于雄辩", pinyin: "shì shí shèng yú xióng biàn", source: "魯迅", japanese: "事実は雄弁に勝る。言葉で語るよりも、実際の学習成果や行動で示すことの重要性。", english: "Facts speak louder than words. Let your actual progress in language demonstrate your dedication." },
  { number: 40, flag: "🇨🇳", chinese: "鞠躬尽瘁", pinyin: "jū gōng jìn cuì", source: "諸葛亮（三国時代の政治家・軍師）", japanese: "全力を尽くして任務を遂行する。学習に対しても全身全霊で取り組む姿勢。", english: "Give your all and fulfill your duty. Throw yourself into your studies with complete commitment." },
  { number: 41, flag: "🇨🇳", chinese: "悬梁刺骨", pinyin: "xuán liáng cì gǔ", source: "中国のことわざ", japanese: "髪を梁に結び、錐で股を刺して眠気を覚まし勉強する。非常に熱心に学習に取り組むことの例え。", english: "Tie your hair to the beam and pierce your thigh to stay awake — an ancient image of extreme dedication to study." },
  { number: 42, flag: "🇨🇳", chinese: "凿壁偷光", pinyin: "záo bì tōu guāng", source: "中国のことわざ", japanese: "壁に穴を開けて隣の家の光を盗んで本を読む。貧しい環境でも工夫して熱心に学ぶ姿勢。", english: "Bore a hole in the wall to borrow a neighbor's candlelight for reading. Even in hardship, find creative ways to keep learning." },
  { number: 43, flag: "🇨🇳", chinese: "学以致用", pinyin: "xué yǐ zhì yòng", source: "中国のことわざ", japanese: "学んだことを実践に生かす。単語や文法を覚えるだけでなく、実際に使ってみることの重要性。", english: "Apply what you learn in practice. Vocabulary and grammar only become truly yours when you use them." },
  { number: 44, flag: "🇨🇳", chinese: "道山学海", pinyin: "dào shān xué hǎi", source: "中国のことわざ", japanese: "学問の道は山のように高く、海のように広い。学ぶべき知識は無限にあるという教え。", english: "The road of learning is as high as a mountain and as wide as a sea. The knowledge you can acquire is truly limitless." },
  { number: 45, flag: "🇨🇳", chinese: "一寸光阴一寸金，寸金难买寸光阴", pinyin: "yī cùn guāng yīn yī cùn jīn ， cùn jīn nán mǎi cùn guāng yīn", source: "中国のことわざ", japanese: "一寸の光陰は一寸の金、一寸の金でも一寸の光陰は買えない。学習に使える時間を無駄にせず、大切にすること。", english: "An inch of time is worth an inch of gold, but an inch of gold cannot buy back an inch of time. Make every study session count." },
  { number: 46, flag: "🇨🇳", chinese: "光阴似箭", pinyin: "guāng yīn sì jiàn", source: "中国のことわざ", japanese: "光陰矢の如し。時間はあっという間に過ぎ去るので、学習の時間を大切にすべきだという戒め。", english: "Time flies like an arrow. Treasure each opportunity to study — once time is gone, it never returns." },
  { number: 47, flag: "🇨🇳", chinese: "书到用时方恨少", pinyin: "shū dào yòng shí fāng hèn shǎo", source: "中国のことわざ", japanese: "本は使う時になって初めて少ないことを悔やむ。いざという時に知識が足りなくて困らないよう、日頃から幅広く学習しておくこと。", english: "You only regret not reading more when you need the knowledge. Study broadly now so you are never caught short later." },
  { number: 48, flag: "🇨🇳", chinese: "读书须用意，一字值千金", pinyin: "dú shū xū yòng yì ， yī zì zhí qiān jīn", source: "中国のことわざ", japanese: "読書には心を注ぐ必要があり、一字には千金の価値がある。単語一つ一つの意味やニュアンスを丁寧に学ぶことの重要性。", english: "Reading requires full attention; a single character is worth a thousand gold coins. Study each new word carefully and thoroughly." },
  { number: 49, flag: "🇨🇳", chinese: "好记性不如烂笔头", pinyin: "hǎo jì xìng bù rú làn bǐ tóu", source: "中国のことわざ", japanese: "良い記憶力も、使い古した筆先には及ばない。単語や文法は、頭で覚えるだけでなく実際に書いて覚えることの重要性。", english: "A good memory is no match for a well-worn pen. Writing vocabulary and phrases down firmly cements them in memory." },
  { number: 50, flag: "🇨🇳", chinese: "书是随时携带的花园", pinyin: "shū shì suí shí xié dài de huā yuán", source: "中国のことわざ", japanese: "本はいつでも持ち歩ける庭園である。読書や学習が人生に豊かさをもたらすことの例え。", english: "A book is a garden you can carry in your pocket. Learning is an endless source of richness and delight wherever you go." },
  { number: 51, flag: "🇨🇳", chinese: "好书如挚友", pinyin: "hǎo shū rú zhì yǒu", source: "中国のことわざ", japanese: "良い本は親友のようである。良質な学習書や教材との出会いを大切にすること。", english: "A good book is like a true friend. Seek out high-quality study materials and let them guide your learning journey." },
  { number: 52, flag: "🇨🇳", chinese: "花有重开日，人无再少年", pinyin: "huā yǒu zhòng kāi rì ， rén wú zài shào nián", source: "中国のことわざ", japanese: "花は再び咲く日があるが、人に再び少年時代は来ない。若いうちに集中して学習に取り組むべきだという戒め。", english: "Flowers can bloom again, but youth never returns. Make the most of your younger years to build a strong language foundation." },
  { number: 53, flag: "🇨🇳", chinese: "为时不晚", pinyin: "wéi shí bù wǎn", source: "中国のことわざ", japanese: "遅すぎることはない。いつから学習を始めても、決して遅くはないという励まし。", english: "It is never too late to begin. No matter your age or starting point, it is always the right time to start learning." },
  { number: 54, flag: "🇨🇳", chinese: "只要功夫深，铁杵磨成针", pinyin: "zhǐ yào gōng fu shēn ， tiě chǔ mó chéng zhēn", source: "中国のことわざ", japanese: "努力が深ければ、鉄の棒も削って針にできる。どんなに難しい単語や文法でも、継続すれば必ず習得できる。", english: "With enough effort, even an iron rod can be ground into a needle. Any vocabulary, however difficult, can be mastered with persistence." },
  { number: 55, flag: "🇨🇳", chinese: "水滴石穿，绳锯木断", pinyin: "shuǐ dī shí chuān ， shéng jù mù duàn", source: "中国のことわざ", japanese: "水滴は石を穿ち、縄の鋸は木を断つ。小さな学習の積み重ねが、最終的に大きな成果を生む。", english: "Dripping water wears through stone; a rope saw cuts through wood. Small, steady study efforts produce enormous results over time." },
  { number: 56, flag: "🇨🇳", chinese: "冰冻三尺，非一日之寒", pinyin: "bīng dòng sān chǐ ， fēi yī rì zhī hán", source: "中国のことわざ", japanese: "氷の厚さが三尺になるのは、一日の寒さによるものではない。語学の習得には長期間の継続的な努力が必要である。", english: "Three feet of ice does not freeze in a single day. Mastery of a language requires months and years of consistent practice." },
  { number: 57, flag: "🇨🇳", chinese: "百尺竿头，更进一步", pinyin: "bǎi chǐ gān tóu ， gèng jìn yí bù", source: "中国のことわざ", japanese: "百尺竿頭に一歩を進む。すでに優れた成績を収めていても、さらに向上を目指して努力すること。", english: "At the top of a hundred-foot pole, take one more step. Even when you are doing well, keep pushing toward greater excellence." },
  { number: 58, flag: "🇨🇳", chinese: "失败是成功之母", pinyin: "shī bài shì chéng gōng zhī mǔ", source: "中国のことわざ", japanese: "失敗は成功の母。学習での間違いは、上達のための重要なステップである。", english: "Failure is the mother of success. Every mistake in language study is a stepping stone toward improvement." },
  { number: 59, flag: "🇨🇳", chinese: "吃一堑，长一智", pinyin: "chī yī qiàn ， zhǎng yī zhì", source: "中国のことわざ", japanese: "一度つまずけば、一つ知恵がつく。学習での失敗や間違いから学び、成長すること。", english: "Each stumble brings new wisdom. Learn from every error and let setbacks fuel your growth." },
  { number: 60, flag: "🇨🇳", chinese: "逆境出人才", pinyin: "nì jìng chū rén cái", source: "中国のことわざ", japanese: "逆境が人材を生み出す。難しい課題や厳しい環境での学習が、真の実力を育てる。", english: "Adversity produces talent. Tackling difficult lessons and challenging content builds your true abilities." },
  { number: 61, flag: "🇨🇳", chinese: "守得云开见月明", pinyin: "shǒu dé yún kāi jiàn yuè míng", source: "中国のことわざ", japanese: "雲が晴れて月明かりが見えるのを待つ。困難な学習を耐え抜けば、必ず理解できる瞬間が訪れる。", english: "Wait for the clouds to clear and the moonlight will appear. Persist through the hard stretches of study, and understanding will come." },
  { number: 62, flag: "🇨🇳", chinese: "否极泰来", pinyin: "pǐ jí tài lái", source: "中国のことわざ", japanese: "悪運が極まれば幸運がやってくる。学習の停滞期を乗り越えれば、必ず成長が実感できる時が来る。", english: "When misfortune reaches its peak, good fortune follows. Push through the plateau and a breakthrough will follow." },
  { number: 63, flag: "🇨🇳", chinese: "不能一口吃成胖子", pinyin: "bù néng yī kǒu chī chéng pàng zi", source: "中国のことわざ", japanese: "一口で太ることはできない。語学学習は一朝一夕にはいかないため、焦らず少しずつ進めるべきだという教え。", english: "You cannot get fat from a single bite. Language learning is gradual — be patient and take it one step at a time." },
  { number: 64, flag: "🇨🇳", chinese: "万事开头难", pinyin: "wàn shì kāi tóu nán", source: "中国のことわざ", japanese: "何事も始めが難しい。学習の初期段階の困難を乗り越えれば、後はスムーズに進むという励まし。", english: "Every endeavor is hard at the beginning. Once you push through the initial challenges of language study, the path gets smoother." },
  { number: 65, flag: "🇨🇳", chinese: "一日之计在于晨", pinyin: "yī rì zhī jì zài yú chén", source: "中国のことわざ", japanese: "一日の計は朝にあり。朝の時間を有効に使って学習することの重要性。", english: "The plan for the day is made in the morning. Use your morning time wisely for study to set a productive tone for the day." },
  { number: 66, flag: "🇨🇳", chinese: "趁热打铁", pinyin: "chèn rè dǎ tiě", source: "中国のことわざ", japanese: "鉄は熱いうちに打て。記憶が新しいうちに復習し、知識を定着させることの重要性。", english: "Strike while the iron is hot. Review new vocabulary right away while it is still fresh in your mind." },
  { number: 67, flag: "🇨🇳", chinese: "有备无患", pinyin: "yǒu bèi wú huàn", source: "『書経』", japanese: "備えあれば憂いなし。事前の準備や予習が学習において重要であることを示す。", english: "Preparedness leaves no room for regret. Preparation and preview before study sessions pays off enormously." },
  { number: 68, flag: "🇨🇳", chinese: "一年之计在于春", pinyin: "yī nián zhī jì zài yú chūn", source: "中国のことわざ", japanese: "一年の計は春にあり。物事は最初が肝心であり、学習計画をしっかり立てることの重要性。", english: "The plan for the year is made in spring. Starting a language study plan early and sticking to it from the start is essential." },
  { number: 69, flag: "🇨🇳", chinese: "捷足先登", pinyin: "jié zú xiān dēng", source: "『史記』", japanese: "先んずれば人を制す。早く行動を起こし、学習を始めることで有利な立場に立てる。", english: "Quick legs claim the hilltop first. Begin your language study without delay and gain an early advantage." },
  { number: 70, flag: "🇨🇳", chinese: "机不可失，时不再来", pinyin: "jī bù kě shī ， shí bù zài lái", source: "中国のことわざ", japanese: "機会は逃してはならず、時は二度と来ない。学習のチャンスを逃さず、今すぐ始めることの重要性。", english: "An opportunity lost does not return. Seize every chance to practice and study — these moments are precious." },
  { number: 71, flag: "🇨🇳", chinese: "背水一战", pinyin: "bèi shuǐ yī zhàn", source: "韓信（漢代の武将）", japanese: "背水の陣。退路を断って決死の覚悟で物事（学習）に取り組むこと。", english: "Fight with your back to the river — do or die. Commit completely to language study with no way back." },
  { number: 72, flag: "🇨🇳", chinese: "星星之火，可以燎原", pinyin: "xīng xīng zhī huǒ ， kě yǐ liáo yuán", source: "毛沢東", japanese: "星のような小さな火でも、広大な野原を焼き尽くすことができる。小さな学習のきっかけが、大きな知識の体系へと発展する。", english: "A single spark can start a prairie fire. A small spark of interest in a language can grow into a lifelong passion." },
  { number: 73, flag: "🇨🇳", chinese: "逐二兔，不得一兔", pinyin: "zhú èr tù ， bù dé yī tù", source: "中国のことわざ", japanese: "二兎を追う者は一兎をも得ず。一度に多くのことを学ぼうとせず、一つずつ集中して取り組むべきだという教え。", english: "Chase two rabbits and catch neither. Focus on one aspect of language learning at a time rather than spreading yourself too thin." },
  { number: 74, flag: "🇨🇳", chinese: "随机应变", pinyin: "suí jī yìng biàn", source: "中国のことわざ", japanese: "臨機応変。状況に応じて柔軟に対応し、学習方法を工夫すること。", english: "Adapt to changing circumstances. Adjust your study methods flexibly to suit different situations and challenges." },
  { number: 75, flag: "🇨🇳", chinese: "如果把才华比作剑，那么勤奋就是磨刀石", pinyin: "rú guǒ bǎ cái huá bǐ zuò jiàn ， nà me qín fèn jiù shì mó dāo shí", source: "中国のことわざ", japanese: "才能を剣に例えるなら、勤勉さは砥石である。才能があっても、日々の学習（研鑽）が不可欠であるという教え。", english: "If talent is a sword, diligence is the whetstone. Natural aptitude matters little without the daily discipline of practice." },
  { number: 76, flag: "🇨🇳", chinese: "十年树木，百年树人", pinyin: "shí nián shù mù ， bǎi nián shù rén", source: "管仲（春秋時代の政治家）", japanese: "木を育てるには十年かかるが、人を育てるには百年かかる。人の教育や学習は長い時間と継続的な努力を要する。", english: "It takes ten years to grow a tree but a hundred years to raise a person. Language mastery requires long-term dedication." },
  { number: 77, flag: "🇨🇳", chinese: "无规矩不成方圆", pinyin: "wú guī jǔ bù chéng fāng yuán", source: "孟子", japanese: "規矩（ルール）なくして方円（秩序）は成らない。学習においても基本的なルールや規律を守ることの重要性。", english: "Without rules, nothing can be accomplished. Structure and discipline — grammar rules, study routines — are the backbone of learning." },
  { number: 78, flag: "🇨🇳", chinese: "三思而后行", pinyin: "sān sī ér hòu xíng", source: "孔子", japanese: "三度考えてから行動する。学習においても、よく考えてから取り組むことの重要性。", english: "Think three times before you act. Consider your study approach carefully and reflect before moving on to new material." },
  { number: 79, flag: "🇨🇳", chinese: "顾左右而言他", pinyin: "gù zuǒ yòu ér yán tā", source: "孟子", japanese: "左右を見て別の話をする。分からないことをごまかさず、正面から学習に向き合うべきだという戒め。", english: "Glance left and right and talk about something else. Face your weak points directly rather than avoiding them." },
  { number: 80, flag: "🇨🇳", chinese: "当局者迷，旁观者清", pinyin: "dāng jú zhě mí ， páng guān zhě qīng", source: "『旧唐書』", japanese: "当事者は迷いやすく、傍観者は状況がよく見える。客観的に自分の学習方法を見直すことの重要性。", english: "The insider is confused; the outsider sees clearly. Step back periodically to evaluate your learning with an objective eye." },
  { number: 81, flag: "🇨🇳", chinese: "惩前毖后", pinyin: "chéng qián bì hòu", source: "『詩経』", japanese: "前の失敗を懲りて、後の失敗を防ぐ。学習でのミスを分析し、次に生かすこと。", english: "Punish the past to prevent the future. Analyze your past mistakes in study so that you do not repeat them." },
  { number: 82, flag: "🇨🇳", chinese: "路遥知马力，日久见人心", pinyin: "lù yáo zhī mǎ lì ， rì jiǔ jiàn rén xīn", source: "中国のことわざ", japanese: "道が遠くて初めて馬の力が分かり、日が経って初めて人の心が分かる。長期間の学習を通じて真の実力が身につく。", english: "Long roads reveal a horse's strength; long time reveals a person's character. Sustained study builds genuine, lasting ability." },
  { number: 83, flag: "🇨🇳", chinese: "听君一席话，胜读十年书", pinyin: "tīng jūn yī xí huà ， shèng dú shí nián shū", source: "中国のことわざ", japanese: "君の一席の話を聞くことは、十年の読書に勝る。優れた指導者や経験者からの直接の教えの価値。", english: "Listening to a wise person's words is better than ten years of reading. Seek good teachers and mentors to accelerate your learning." },
  { number: 84, flag: "🇨🇳", chinese: "近水知鱼性，近山识鸟音", pinyin: "jìn shuǐ zhī yú xìng ， jìn shān shí niǎo yīn", source: "『増広賢文』", japanese: "水に近づけば魚の性質を知り、山に近づけば鳥の音を識る。その言語が話される環境や文化に触れることが、学習の近道。", english: "Near the water you learn the fish's nature; near the mountain you recognize the bird's call. Immersion in the target language and culture is the fastest path to fluency." },
  { number: 85, flag: "🇨🇳", chinese: "入乡随俗", pinyin: "rù xiāng suí sú", source: "中国のことわざ", japanese: "郷に入っては郷に従う。外国語を学ぶ際は、その国の文化や習慣も受け入れることの重要性。", english: "When in a village, follow its customs. Embrace the culture behind the language you are learning — it enriches your understanding." },
  { number: 86, flag: "🇨🇳", chinese: "君子之交淡如水", pinyin: "jūn zǐ zhī jiāo dàn rú shuǐ", source: "『荘子』", japanese: "君子の交わりは淡きこと水の如し。学習仲間とは、互いに高め合うさっぱりとした良い関係を築くこと。", english: "A gentleman's friendship is as clear as water. Build clean, mutually supportive relationships with your study partners." },
  { number: 87, flag: "🇨🇳", chinese: "行要好伴，住要好邻", pinyin: "xíng yào hǎo bàn ， zhù yào hǎo lín", source: "中国のことわざ", japanese: "旅には良い道連れ、住むには良い隣人が必要。学習においても良い仲間や環境が重要であることを示す。", english: "Travel needs good companions; living needs good neighbors. The right study environment and community make all the difference." },
  { number: 88, flag: "🇨🇳", chinese: "人心齐，泰山移", pinyin: "rén xīn qí ， tài shān yí", source: "中国のことわざ", japanese: "人々の心が一つになれば、泰山をも動かせる。仲間と協力して学習することの大きな力。", english: "When people are united, even Mount Tai can be moved. Studying together with others multiplies everyone's motivation and progress." },
  { number: 89, flag: "🇨🇳", chinese: "种瓜得瓜，种豆得豆", pinyin: "zhòng guā dé guā ， zhòng dòu dé dòu", source: "中国のことわざ", japanese: "瓜の種をまけば瓜がなり、豆の種をまけば豆がなる。努力した分だけ結果が得られるという因果応報の教え。", english: "Plant melons and harvest melons; plant beans and harvest beans. The effort you put into study is exactly what you will reap." },
  { number: 90, flag: "🇨🇳", chinese: "一步一个脚印", pinyin: "yī bù yī gè jiǎo yìn", source: "中国のことわざ", japanese: "一歩一歩足跡を残す。着実に学習を進め、確かな実力を身につけること。", english: "Every step leaves a footprint. Advance steadily in your studies, leaving a solid trail of knowledge behind you." },
  { number: 91, flag: "🇨🇳", chinese: "大处着眼，小处着手", pinyin: "dà chù zhuó yǎn ， xiǎo chù zhuó shǒu", source: "中国のことわざ", japanese: "大きな目標を見据えつつ、小さなことから着手する。語学の習得という大きな目標を持ちながら、日々の単語学習をコツコツ行うこと。", english: "Keep the big picture in mind while starting with small steps. Set ambitious language goals, then tackle them one vocabulary word at a time." },
  { number: 92, flag: "🇨🇳", chinese: "身体力行", pinyin: "shēn tǐ lì xíng", source: "『淮南子』", japanese: "自ら実践する。学んだ知識を実際に使って行動することの重要性。", english: "Practice what you preach. Put the words you have studied into real action — use the language, do not just memorize it." },
  { number: 93, flag: "🇨🇳", chinese: "难得糊涂", pinyin: "nán dé hú tú", source: "鄭板橋（清代の書家・画家）", japanese: "糊塗なるは得難し。時には細かいことにこだわりすぎず、大局的に学習を進めることも大切である。", english: "It is rare and precious to keep a relaxed spirit. Sometimes it is best not to obsess over details — keep the bigger learning picture in view." },
  { number: 94, flag: "🇨🇳", chinese: "塞翁失马，焉知非福", pinyin: "sài wēng shī mǎ ， yān zhī fēi fú", source: "『淮南子』", japanese: "人間万事塞翁が馬。試験の不合格など一見悪い出来事も、後の学習のモチベーションなど良い結果につながるかもしれない。", english: "The old man lost his horse — who knows if it was good or bad? A failed exam or a bad study day may ultimately lead you to something better." },
  { number: 95, flag: "🇨🇳", chinese: "人无完人，金无足赤", pinyin: "rén wú wán rén ， jīn wú zú chì", source: "中国のことわざ", japanese: "完璧な人間はおらず、純度100%の金もない。学習において完璧を求めすぎず、間違いを恐れないこと。", english: "No person is perfect; no gold is pure. Do not demand perfection of yourself in learning — embrace mistakes and keep going." },
  { number: 96, flag: "🇨🇳", chinese: "书山有路勤为径", pinyin: "shū shān yǒu lù qín wèi jìng", source: "韓愈", japanese: "書物の山に道はあるが、勤勉さがその道である。どんなに難しい内容も、勤勉に取り組めば必ず道が開ける。", english: "The mountain of books has a path, and diligence is that path. However vast the material, hard work will always open the way." },
  { number: 97, flag: "🇨🇳", chinese: "三更灯火五更鸡", pinyin: "sān gēng dēng huǒ wǔ gēng jī", source: "顔真卿（唐代の書家）", japanese: "夜中の三更に灯をともし、夜明けの五更に鶏が鳴く。夜遅くまで、また早朝から学習に励む姿勢。", english: "Burn the midnight oil and rise at cockcrow. Dedicate extra hours to study — early mornings and late nights — to reach your goals." },
  { number: 98, flag: "🇨🇳", chinese: "宝剑锋从磨砺出，梅花香自苦寒来", pinyin: "bǎo jiàn fēng cóng mó lì chū ， méi huā xiāng zì kǔ hán lái", source: "中国のことわざ", japanese: "宝剣の鋭さは研磨から生まれ、梅の花の香りは厳しい寒さから生まれる。苦しい学習の先に、美しい成果が待っている。", english: "A fine sword's edge comes from grinding; the plum blossom's fragrance comes from bitter cold. The hardships of study lead to beautiful results." },
  { number: 99, flag: "🇨🇳", chinese: "不积跬步，无以至千里", pinyin: "bù jī kuǐ bù ， wú yǐ zhì qiān lǐ", source: "荀子", japanese: "小さな一歩を積み重ねなければ、千里の道には到達できない。毎日の単語学習の積み重ねが語学力を作る。", english: "Without accumulating tiny steps, you cannot reach a thousand miles. Daily vocabulary study is the foundation of ultimate language mastery." },
  { number: 100, flag: "🇨🇳", chinese: "锲而不舍，金石可镂", pinyin: "qiè ér bù shě ， jīn shí kě lòu", source: "荀子", japanese: "刻み続ければ、金属や石にも彫ることができる。諦めずに学習を続ければ、どんな難しい言語も習得できる。", english: "Carve without stopping, and even metal and stone can be engraved. Never give up on studying Chinese — with perseverance, anything is achievable." },
  { number: 101, flag: "🇺🇸", chinese: "天才是百分之一的灵感加百分之九十九的汗水", pinyin: "tiān cái shì bǎi fēn zhī yī de líng gǎn jiā bǎi fēn zhī jiǔ shí jiǔ de hàn shuǐ", source: "トーマス・エジソン（米・発明家）", japanese: "天才は1%のひらめきと99%の努力。単語学習も日々の地道な努力が最も重要であるという教え。", english: "Genius is one percent inspiration and ninety-nine percent perspiration. Daily vocabulary study matters far more than natural talent." },
  { number: 102, flag: "🇬🇧", chinese: "知识就是力量", pinyin: "zhī shí jiù shì lì liàng", source: "フランシス・ベーコン（英・哲学者）", japanese: "知は力なり。語学の知識を身につけることで、世界を広げ、自分の可能性を広げることができる。", english: "Knowledge is power. Mastering a language expands your world and opens up new possibilities." },
  { number: 103, flag: "🇩🇪", chinese: "我并没有什么特殊的才能，我只是充满着强烈的好奇心", pinyin: "wǒ bìng méi yǒu shén me tè shū de cái néng ， wǒ zhǐ shì chōng mǎn zhe qiáng liè de hào qí xīn", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "私には特別な才能はない。ただ、ものすごく好奇心が強いだけだ。新しい言語や単語に対する好奇心が学習の原動力になる。", english: "I have no special talent; I am only passionately curious. Let curiosity about new words and languages drive your learning." },
  { number: 104, flag: "🇩🇪", chinese: "不要把学习看成是任务，而是一个令人羡慕的机会", pinyin: "bú yào bǎ xué xí kàn chéng shì rèn wù ， ér shì yí gè lìng rén xiàn mù de jī huì", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "学習を義務と考えるのではなく、羨むべき機会と捉えなさい。前向きな姿勢で学習に取り組むことの重要性。", english: "Do not regard learning as an obligation but as an enviable opportunity. Approach your studies with a positive, enthusiastic mindset." },
  { number: 105, flag: "🇩🇪", chinese: "成功=艰苦的劳动+正确的方法+少谈空话", pinyin: "chéng gōng = jiān kǔ de láo dòng + zhèng què de fāng fǎ + shǎo tán kōng huà", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "成功＝厳しい労働＋正しい方法＋無駄話をしないこと。語学学習にも正しいメソッドと継続的な努力が必要である。", english: "Success = hard work + the right method + less empty talk. Language learning requires both effective methods and consistent effort." },
  { number: 106, flag: "🇬🇧", chinese: "如果我看得更远，那是因为我站在巨人的肩膀上", pinyin: "rú guǒ wǒ kàn dé gèng yuǎn ， nà shì yīn wèi wǒ zhàn zài jù rén de jiān bǎng shàng", source: "アイザック・ニュートン（英・物理学者）", japanese: "私が遠くを見ることができたのは、巨人たちの肩に乗っていたからだ。先人たちが築いた文法や辞書を活用して学ぶことの意義。", english: "If I have seen further, it is by standing on the shoulders of giants. Build on the grammar books and dictionaries left by those before you." },
  { number: 107, flag: "🇬🇧", chinese: "真理的大海，让未发现的一切事物躺卧在我的眼前，任我去探寻", pinyin: "zhēn lǐ de dà hǎi ， ràng wèi fā xiàn de yī qiè shì wù tǎng wò zài wǒ de yǎn qián ， rèn wǒ qù tàn xún", source: "アイザック・ニュートン（英・物理学者）", japanese: "真理の大海は、未発見のすべてを私の目の前に横たわらせ、探求を待っている。未知の単語や表現を探求する楽しさ。", english: "The great ocean of truth lies undiscovered before me. Delight in the vast world of language still waiting to be explored." },
  { number: 108, flag: "🇺🇸", chinese: "学习另一种语言不仅是学会用另一种文字去表达一个意思，而是用另一种思维方式去思考事情", pinyin: "xué xí lìng yī zhǒng yǔ yán bù jǐn shì xué huì yòng lìng yī zhǒng wén zì qù biǎo dá yí gè yì si ， ér shì yòng lìng yī zhǒng sī wéi fāng shì qù sī kǎo shì qíng", source: "フローラ・ルイス（米・ジャーナリスト）", japanese: "別の言語を学ぶことは、同じ物事を別の言葉で表現することではなく、別の思考法を学ぶことである。", english: "Learning another language is not only learning different words for the same things, but learning another way to think about things." },
  { number: 109, flag: "🇮🇹", chinese: "每种不同的语言都是一种不同的生活视角", pinyin: "měi zhǒng bù tóng de yǔ yán dōu shì yī zhǒng bù tóng de shēng huó shì jiǎo", source: "フェデリコ・フェリーニ（伊・映画監督）", japanese: "異なる言語は、それぞれ異なる人生の視点である。言語を学ぶことで新しい世界の見方を獲得できる。", english: "A different language is a different vision of life. Each language you learn gives you an entirely new way to see the world." },
  { number: 110, flag: "🇯🇵", chinese: "学习另一种语言就像变成另一个人", pinyin: "xué xí lìng yī zhǒng yǔ yán jiù xiàng biàn chéng lìng yí gè rén", source: "村上春樹（日・小説家）", japanese: "別の言語を学ぶことは、別の人間になるようなものだ。新しい言語を話すときの新しい自分を楽しむこと。", english: "Learning a new language is like becoming a new person. Enjoy discovering the new version of yourself that emerges in Chinese." },
  { number: 111, flag: "🇬🇧", chinese: "只要你学会各种语言，在哪里都像是在家里", pinyin: "zhǐ yào nǐ xué huì gè zhǒng yǔ yán ， zài nǎ li dōu xiàng shì zài jiā lǐ", source: "エドマンド・デ・ワール（英・作家）", japanese: "言語を学べば、どこにいても自分の家にいるように感じられる。語学がもたらす安心感と自由。", english: "To know another language is to have a second soul. Wherever you go, language knowledge makes you feel at home." },
  { number: 112, flag: "🇬🇧", chinese: "一种语言限定了你的发展方向，两种语言就在沿途为你打开每一扇门", pinyin: "yī zhǒng yǔ yán xiàn dìng le nǐ de fā zhǎn fāng xiàng ， liǎng zhǒng yǔ yán jiù zài yán tú wèi nǐ dǎ kāi měi yī shàn mén", source: "フランク・スミス（英・言語学者）", japanese: "一つの言語は人生の廊下を定めるが、二つの言語はその道中のすべての扉を開いてくれる。", english: "One language sets you in a corridor for life; two languages open every door along the way." },
  { number: 113, flag: "🇬🇧", chinese: "你永远没有办法彻底的明白一门语言，直到你至少学会了第二种语言", pinyin: "nǐ yǒng yuǎn méi yǒu bàn fǎ chè dǐ de míng bái yī mén yǔ yán ， zhí dào nǐ zhì shǎo xué huì le dì èr zhǒng yǔ yán", source: "ジェフリー・ウィランズ（英・作家）", japanese: "少なくとも第二言語を学ぶまでは、一つの言語を完全に理解することはできない。母語の理解も深まるという教え。", english: "You can never understand one language until you understand at least two. Learning Chinese deepens your understanding of your own language too." },
  { number: 114, flag: "🇦🇹", chinese: "语言对我的束缚就是语言对我的世界的束缚", pinyin: "yǔ yán duì wǒ de shù fù jiù shì yǔ yán duì wǒ de shì jiè de shù fù", source: "ルートヴィヒ・ウィトゲンシュタイン（墺・哲学者）", japanese: "私の言語の限界は、私の世界の限界を意味する。語彙を増やすことで、自分の世界を広げることができる。", english: "The limits of my language mean the limits of my world. Every new word you learn expands the boundaries of your world." },
  { number: 115, flag: "🇺🇸", chinese: "语言就是一个文化的指路标，它告诉你人从哪里来，他们又要去哪里", pinyin: "yǔ yán jiù shì yí gè wén huà de zhǐ lù biāo ， tā gào sù nǐ rén cóng nǎ lǐ lái ， tā men yòu yào qù nǎ lǐ", source: "リタ・メイ・ブラウン（米・作家）", japanese: "言語は文化の道標である。単語の背景にある文化や歴史を学ぶことの重要性。", english: "Language is a roadmap of a culture. It tells you where its people came from and where they are going." },
  { number: 116, flag: "🇩🇪", chinese: "那些不懂得外语的人也并不了解他们自己", pinyin: "nà xiē bù dǒng de wài yǔ de rén yě bìng bù liǎo jiě tā men zì jǐ", source: "ヨハン・ヴォルフガング・フォン・ゲーテ（独・文豪）", japanese: "外国語を知らない者は、自分自身のことも知らない。他言語との比較によって自己理解が深まる。", english: "Those who know nothing of foreign languages know nothing of their own. Studying Chinese enriches your understanding of your native tongue." },
  { number: 117, flag: "🇿🇦", chinese: "如果你跟一个人用他听得懂的语言说一件事，那这件事就听进他的头脑里，但是如果你用他的语言说一件事，那就被听进他的心里", pinyin: "rú guǒ nǐ gēn yí gè rén yòng tā tīng de dǒng de yǔ yán shuō yī jiàn shì ， nà zhè jiàn shì jiù tīng jìn tā de tóu nǎo lǐ ， dàn shì rú guǒ nǐ yòng tā de yǔ yán shuō yī jiàn shì ， nà jiù bèi tīng jìn tā de xīn lǐ", source: "ネルソン・マンデラ（南ア・政治家）", japanese: "相手が理解できる言語で話しかければ頭に届き、相手の母語で話しかければ心に届く。語学学習の究極の目的。", english: "If you talk to a man in a language he understands, that goes to his head. If you talk to him in his language, that goes to his heart." },
  { number: 118, flag: "🇫🇷", chinese: "学会另一种语言就像是拥有另一个灵魂", pinyin: "xué huì lìng yī zhǒng yǔ yán jiù xiàng shì yōng yǒu lìng yí gè líng hún", source: "カール大帝（仏・神聖ローマ皇帝）", japanese: "別の言語を学ぶことは、もう一つの魂を持つようなものだ。言語習得による精神的な豊かさ。", english: "To have another language is to possess a second soul. Language learning enriches you spiritually as well as practically." },
  { number: 119, flag: "🇨🇿", chinese: "你懂得越多的语言，你就越能成为一个完整的人", pinyin: "nǐ dǒng de yuè duō de yǔ yán ， nǐ jiù yuè néng chéng wéi yí gè wán zhěng de rén", source: "トマーシュ・マサリク（チェコ・政治家）", japanese: "知っている言語が多ければ多いほど、より完全な人間になれる。多言語学習の価値。", english: "The more languages you know, the more of a person you are. Learning multiple languages makes you a more complete human being." },
  { number: 120, flag: "🇬🇧", chinese: "语言的知识就是通往智慧的大门", pinyin: "yǔ yán de zhī shí jiù shì tōng wǎng zhì huì de dà mén", source: "ロジャー・ベーコン（英・哲学者・科学者）", japanese: "言語の知識は知恵への扉である。単語学習がすべての学問の基礎となること。", english: "Knowledge of languages is the gateway to wisdom. Vocabulary study is the foundation of all other learning." },
  { number: 121, flag: "🇩🇪", chinese: "教育是在一个人忘记了他在学校里学到的一切之后剩下的东西", pinyin: "jiào yù shì zài yí gè rén wàng jì le tā zài xué xiào lǐ xué dào de yī qiè zhī hòu shèng xià de dōng xī", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "教育とは、学校で学んだことをすべて忘れた後に残るものである。詰め込みではなく、本質的な学習の重要性。", english: "Education is what remains after one has forgotten everything learned in school. Seek deep understanding, not just memorization." },
  { number: 122, flag: "🇩🇪", chinese: "重要的是不要停止提问。好奇心有其存在的理由", pinyin: "zhòng yào de shì bú yào tíng zhǐ tí wèn 。 hào qí xīn yǒu qí cún zài de lǐ yóu", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "大切なのは疑問を持ち続けることだ。好奇心には存在する理由がある。分からない単語を常に調べる姿勢。", english: "The important thing is not to stop questioning. Curiosity has its own reason for existing. Always look up unfamiliar words." },
  { number: 123, flag: "🇺🇸", chinese: "我没有失败。我只是找到了一万种行不通的方法", pinyin: "wǒ méi yǒu shī bài 。 wǒ zhǐ shì zhǎo dào le yī wàn zhǒng xíng bù tōng de fāng fǎ", source: "トーマス・エジソン（米・発明家）", japanese: "私は失敗したことがない。ただ、うまくいかない方法を1万通り見つけただけだ。学習での間違いを恐れないこと。", english: "I have not failed — I have just found ten thousand ways that do not work. Fear no mistake; each one brings you closer to success." },
  { number: 124, flag: "🇬🇧", chinese: "读书给人以快乐、给人以光彩、给人以才干", pinyin: "dú shū gěi rén yǐ kuài lè 、 gěi rén yǐ guāng cǎi 、 gěi rén yǐ cái gàn", source: "フランシス・ベーコン（英・哲学者）", japanese: "読書は人に喜びを与え、輝きを与え、才能を与える。外国語での読書がもたらす恩恵。", english: "Reading maketh a full man; conference a ready man; and writing an exact man. Balance reading, speaking, and writing in your study." },
  { number: 125, flag: "🇷🇺", chinese: "理想的书籍是智慧的钥匙", pinyin: "lǐ xiǎng de shū jí shì zhì huì de yào shi", source: "レフ・トルストイ（露・文豪）", japanese: "理想的な書物は知恵の鍵である。良質なテキストや単語帳を選ぶことの重要性。", english: "An ideal book is the key to wisdom. Choose excellent textbooks and study materials carefully." },
  { number: 126, flag: "🇷🇺", chinese: "没有智慧的头脑，就像没有蜡烛的灯笼", pinyin: "méi yǒu zhì huì de tóu nǎo ， jiù xiàng méi yǒu là zhú de dēng lóng", source: "レフ・トルストイ（露・文豪）", japanese: "知恵のない頭脳は、ろうそくのない提灯のようなものだ。知識を蓄えることの必要性。", english: "A brain without knowledge is like a lantern without a candle. Constantly add to your store of vocabulary and grammar." },
  { number: 127, flag: "🇷🇺", chinese: "如果学习只在于模仿，那么我们就不会有科学，也不会有技术", pinyin: "rú guǒ xué xí zhǐ zài yú mó fǎng ， nà me wǒ men jiù bú huì yǒu kē xué ， yě bú huì yǒu jì shù", source: "マクシム・ゴーリキー（露・文豪）", japanese: "学習が単なる模倣に過ぎないなら、科学も技術も存在しない。単語を覚えるだけでなく、自分で文を作る応用力。", english: "If learning were only imitation, there would be no science or technology. Do not just memorize words — apply them creatively." },
  { number: 128, flag: "🇬🇧", chinese: "无知者比有知者更自信", pinyin: "wú zhī zhě bǐ yǒu zhī zhě gèng zì xìn", source: "チャールズ・ダーウィン（英・生物学者）", japanese: "無知な者は、知恵ある者よりも自信に満ちている。学習を進めるほど自分の不足に気づき、謙虚になるべきだという教え。", english: "Ignorance more frequently begets confidence than does knowledge. The more you learn, the more you realize how much you still have to discover." },
  { number: 129, flag: "🇫🇷", chinese: "好奇心造就科学家和诗人", pinyin: "hào qí xīn zào jiù kē xué jiā hé shī rén", source: "アナトール・フランス（仏・作家）", japanese: "好奇心が科学者と詩人を創る。言葉に対する好奇心が語学力を飛躍させる。", english: "Curiosity is the mother of scientists and poets. Curiosity about language will take your learning to new heights." },
  { number: 130, flag: "🇷🇺", chinese: "读书是最好的学习。追随伟大人物的思想，是最富有趣味的一门科学", pinyin: "dú shū shì zuì hǎo de xué xí 。 zhuī suí wěi dà rén wù de sī xiǎng ， shì zuì fù yǒu qù wèi de yī mén kē xué", source: "アレクサンドル・プーシキン（露・詩人）", japanese: "読書は最高の学習である。偉大な人物の思想を追うことは最も面白い。名言や文学を通じて言語を学ぶ楽しさ。", english: "Reading is the best learning. Following the thoughts of great minds is the most interesting study of all." },
  { number: 131, flag: "🇷🇺", chinese: "科学的未来只能属于勤奋而谦虚的年轻一代", pinyin: "kē xué de wèi lái zhǐ néng shǔ yú qín fèn ér qiān xū de nián qīng yí dài", source: "イワン・パブロフ（露・生理学者）", japanese: "科学の未来は、勤勉で謙虚な若い世代にのみ属する。語学学習においても勤勉さと謙虚さが不可欠。", english: "The future of science belongs to the industrious and humble young generation. Diligence and humility are essential in language learning too." },
  { number: 132, flag: "🇺🇸", chinese: "惊奇就是科学的种子", pinyin: "jīng qí jiù shì kē xué de zhǒng zi", source: "トーマス・エジソン（米・発明家）", japanese: "驚きは科学の種である。新しい単語や表現に出会ったときの感動を大切にすること。", english: "Wonder is the seed of science. Cherish the sense of wonder you feel when you encounter a new word or expression." },
  { number: 133, flag: "🇫🇷", chinese: "在科学上重要的是研究出来的东西，不是研究者个人", pinyin: "zài kē xué shàng zhòng yào de shì yán jiū chū lái de dōng xī ， bú shì yán jiū zhě gè rén", source: "マリー・キュリー（仏・物理学者・化学者）", japanese: "科学において重要なのは発見された「事柄」であり、研究者「個人」ではない。学習の成果そのものに集中すること。", english: "In science, what matters is the thing discovered, not the discoverer. Focus on the knowledge itself, not on outward appearances." },
  { number: 134, flag: "🇬🇧", chinese: "只有顺从自然，才能驾驭自然", pinyin: "zhǐ yǒu shùn cóng zì rán ， cái néng jià yù zì rán", source: "フランシス・ベーコン（英・哲学者）", japanese: "自然に従ってこそ、自然を支配できる。言語の自然な法則（文法や語法）に逆らわず、素直に学ぶこと。", english: "Nature, to be commanded, must be obeyed. Learn the natural rules and patterns of Chinese — grammar and usage — and they will serve you well." },
  { number: 135, flag: "🇫🇷", chinese: "科学的探讨和研究，其本身就含有至美，其本身给人的愉快就是酬报", pinyin: "kē xué de tàn tǎo hé yán jiū ， qí běn shēn jiù hán yǒu zhì měi ， qí běn shēn gěi rén de yú kuài jiù shì chóu bào", source: "マリー・キュリー（仏・物理学者・化学者）", japanese: "探求と研究そのものに美しさがあり、その喜び自体が報酬である。学ぶプロセス自体を楽しむこと。", english: "Scientific investigation and research contain their own beauty; the joy they bring is its own reward. Enjoy the process of learning itself." },
  { number: 136, flag: "🇩🇪", chinese: "科学是永无止境的，它是一个永恒之谜", pinyin: "kē xué shì yǒng wú zhǐ jìng de ， tā shì yí gè yǒng héng zhī mí", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "科学に終わりはなく、永遠の謎である。語学学習も一生続く探求の旅である。", english: "Science is inexhaustible — an eternal mystery. Language learning is likewise a lifelong journey of discovery." },
  { number: 137, flag: "🇷🇺", chinese: "天才只意味着终身不懈的努力", pinyin: "tiān cái zhǐ yì wèi zhe zhōng shēn bù xiè de nǔ lì", source: "ドミトリ・メンデレーエフ（露・化学者）", japanese: "天才とは、生涯にわたる絶え間ない努力を意味するに過ぎない。毎日の単語学習の積み重ねが天才を作る。", english: "Genius means nothing more than lifelong, unrelenting effort. Daily, dedicated vocabulary study is the path to language mastery." },
  { number: 138, flag: "🇬🇧", chinese: "我之所以能在科学上成功，最重要的一点就是对科学的热爱，坚持长期探索", pinyin: "wǒ zhī suǒ yǐ néng zài kē xué shàng chéng gōng ， zuì zhòng yào de yì diǎn jiù shì duì kē xué de rè ài ， jiān chí cháng qī tàn suǒ", source: "チャールズ・ダーウィン（英・生物学者）", japanese: "成功できた最も重要な理由は、情熱と長期的な探求の継続である。語学も長期戦であることを覚悟する。", english: "The most important factor in my success was the love of science and long-continued patient investigation. Long-term passion and patience are essential in language learning." },
  { number: 139, flag: "🇮🇹", chinese: "真理终究是藏不住的……谬误总是带着面具", pinyin: "zhēn lǐ zhōng jiū shì cáng bú zhù de …… miù wù zǒng shì dài zhe miàn jù", source: "レオナルド・ダ・ヴィンチ（伊・芸術家・科学者）", japanese: "真理は隠し通せない。誤りは常に仮面をかぶっている。正しい語法や発音を追求する姿勢。", english: "Truth will ultimately prevail; error always wears a mask. Pursue correct grammar and pronunciation — do not settle for approximations." },
  { number: 140, flag: "🇮🇹", chinese: "数学是一门美丽的语言学", pinyin: "shù xué shì yī mén měi lì de yǔ yán xué", source: "レオナルド・ダ・ヴィンチ（伊・芸術家・科学者）", japanese: "数学は美しい言語学である。言語にも数学のような論理的な美しさがあること。", english: "Mathematics is a beautiful branch of linguistics. Language has its own kind of logical beauty, just like mathematics." },
  { number: 141, flag: "🇬🇷", chinese: "学习是灵魂的食物", pinyin: "xué xí shì líng hún de shí wù", source: "ソクラテス（古代ギリシャ・哲学者）", japanese: "学習は魂の食べ物である。新しい言葉を学ぶことで精神が豊かになる。", english: "Learning is the food of the soul. Feed your mind with new words every day and watch your inner world grow." },
  { number: 142, flag: "🇬🇷", chinese: "我知道我一无所知", pinyin: "wǒ zhī dào wǒ yī wú suǒ zhī", source: "ソクラテス（古代ギリシャ・哲学者）", japanese: "私は自分が何も知らないということを知っている（無知の知）。学習における究極の謙虚さ。", english: "I know that I know nothing. True knowledge begins with the humility to admit how much you have yet to learn." },
  { number: 143, flag: "🇬🇷", chinese: "教育不是灌输，而是点燃火焰", pinyin: "jiào yù bú shì guàn shū ， ér shì diǎn rán huǒ yàn", source: "ソクラテス（古代ギリシャ・哲学者）", japanese: "教育とは知識を詰め込むことではなく、炎を点火することだ。自ら進んで学ぶ情熱を持つこと。", english: "Education is not the filling of a pot but the lighting of a fire. The goal of language study is to ignite a lasting passion for communication." },
  { number: 144, flag: "🇬🇷", chinese: "未经反思的生活是不值得过的", pinyin: "wèi jīng fǎn sī de shēng huó shì bù zhí dé guò de", source: "ソクラテス（古代ギリシャ・哲学者）", japanese: "反省のない人生は生きる価値がない。自分の学習方法や進捗を常に振り返ること。", english: "An unexamined life is not worth living. Regularly reflect on your learning methods and progress to keep improving." },
  { number: 145, flag: "🇬🇷", chinese: "智慧开始于惊奇", pinyin: "zhì huì kāi shǐ yú jīng qí", source: "ソクラテス（古代ギリシャ・哲学者）", japanese: "知恵は驚きから始まる。未知の言語や文化に対する驚きが学習の第一歩。", english: "Wisdom begins in wonder. Let the wonder of encountering a new language be the spark that lights your desire to learn." },
  { number: 146, flag: "🇬🇷", chinese: "良好的开端是成功的一半", pinyin: "liáng hǎo de kāi duān shì chéng gōng de yí bàn", source: "プラトン（古代ギリシャ・哲学者）", japanese: "良い始まりは成功の半分である。学習の初期段階でしっかりとした基礎を築くことの重要性。", english: "The beginning is the most important part of any work. Build a solid foundation of basic Chinese early — it will support everything you add later." },
  { number: 147, flag: "🇬🇷", chinese: "知识是灵魂的指路明灯", pinyin: "zhī shí shì líng hún de zhǐ lù míng dēng", source: "プラトン（古代ギリシャ・哲学者）", japanese: "知識は魂の道標である。語学力が人生の選択肢を広げてくれる。", english: "Knowledge is the food of the soul. Language study nourishes the mind and opens up new paths in life." },
  { number: 148, flag: "🇬🇷", chinese: "卓越不是一种行为，而是一种习惯", pinyin: "zhuó yuè bú shì yī zhǒng xíng wéi ， ér shì yī zhǒng xí guàn", source: "アリストテレス（古代ギリシャ・哲学者）", japanese: "卓越性は単発の行動ではなく、習慣である。毎日の単語学習を習慣化することの重要性。", english: "Excellence is not an act but a habit. Make daily vocabulary study a habit, and excellence will follow." },
  { number: 149, flag: "🇬🇷", chinese: "教育的根是苦的，但其果实是甜的", pinyin: "jiào yù de gēn shì kǔ de ， dàn qí guǒ shí shì tián de", source: "アリストテレス（古代ギリシャ・哲学者）", japanese: "教育の根は苦いが、その果実は甘い。単語の暗記は辛いが、自由に話せるようになった時の喜びは大きい。", english: "The roots of education are bitter, but the fruit is sweet. Memorizing vocabulary is hard work, but the freedom to communicate fluently is priceless." },
  { number: 150, flag: "🇬🇷", chinese: "求知是人类的本性", pinyin: "qiú zhī shì rén lèi de běn xìng", source: "アリストテレス（古代ギリシャ・哲学者）", japanese: "知を求めることは人間の本性である。新しい言葉を学びたいという自然な欲求を大切にすること。", english: "Knowing yourself is the beginning of all wisdom. Understand your own strengths and weaknesses in Chinese to guide your study plan." },
  { number: 151, flag: "🇬🇷", chinese: "吾爱吾师，吾更爱真理", pinyin: "wú ài wú shī ， wú gèng ài zhēn lǐ", source: "アリストテレス（古代ギリシャ・哲学者）", japanese: "私は師を愛するが、それ以上に真理を愛する。教えを鵜呑みにせず、自ら正しい語法を探求する姿勢。", english: "I love my teacher, but I love truth more. Do not simply follow received wisdom — explore Chinese actively and seek genuine understanding." },
  { number: 152, flag: "🇬🇷", chinese: "给我一个支点，我就能撬动地球", pinyin: "gěi wǒ yí gè zhī diǎn ， wǒ jiù néng qiào dòng dì qiú", source: "アルキメデス（古代ギリシャ・数学者）", japanese: "支点を与えられれば、地球をも動かしてみせる。確固たる基礎（文法や基本単語）があれば、どんな高度な内容も理解できる。", english: "Give me a lever long enough and a place to stand, and I will move the earth. A solid grasp of grammar and core vocabulary can unlock any level of Chinese." },
  { number: 153, flag: "🇬🇧", chinese: "时间是检验真理的最好标准", pinyin: "shí jiān shì jiǎn yàn zhēn lǐ de zuì hǎo biāo zhǔn", source: "フランシス・ベーコン（英・哲学者）", japanese: "時間は真理を検証する最高の基準である。長期間の学習を通じて、本当に役立つ知識が定着する。", english: "Time is the best judge of truth. Knowledge that truly sticks comes from long, patient study." },
  { number: 154, flag: "🇬🇧", chinese: "习惯是一种顽强而巨大的力量，它可以主宰人生", pinyin: "xí guàn shì yī zhǒng wán qiáng ér jù dà de lì liàng ， tā kě yǐ zhǔ zǎi rén shēng", source: "フランシス・ベーコン（英・哲学者）", japanese: "習慣は強大で巨大な力であり、人生を支配する。語学学習を毎日の習慣にすることの絶大な効果。", english: "Habit is a tenacious and mighty force that can govern one's life. Make Chinese study a daily habit and it will transform your abilities." },
  { number: 155, flag: "🇬🇧", chinese: "读书使人充实，讨论使人机智，笔记使人准确", pinyin: "dú shū shǐ rén chōng shí ， tǎo lùn shǐ rén jī zhì ， bǐ jì shǐ rén zhǔn què", source: "フランシス・ベーコン（英・哲学者）", japanese: "読書は人を豊かにし、議論は人を機敏にし、メモは人を正確にする。読む・話す・書くのバランスの取れた学習法。", english: "Reading maketh a full man, conference a ready man, and writing an exact man. A balanced approach — reading, speaking, and writing — produces well-rounded fluency." },
  { number: 156, flag: "🇬🇧", chinese: "知识本身并没有告诉人们怎样运用它，运用的方法乃在书本之外", pinyin: "zhī shí běn shēn bìng méi yǒu gào sù rén men zěn yàng yùn yòng tā ， yùn yòng de fāng fǎ nǎi zài shū běn zhī wài", source: "フランシス・ベーコン（英・哲学者）", japanese: "知識自体はその使い方を教えてくれない。使い方は実践の中にある。単語を覚えるだけでなく、実際に使ってみること。", english: "Knowledge itself does not tell us how to use it; the method of application lies beyond books. Put your vocabulary to use in real conversations." },
  { number: 157, flag: "🇫🇷", chinese: "我思故我在", pinyin: "wǒ sī gù wǒ zài", source: "ルネ・デカルト（仏・哲学者・数学者）", japanese: "我思う、故に我在り。自ら考え、理解しながら学習を進めることの重要性。", english: "I think, therefore I am. Think actively and reflectively as you study — understanding matters more than rote memorization." },
  { number: 158, flag: "🇫🇷", chinese: "阅读一切好书如同和过去最杰出的人谈话", pinyin: "yuè dú yī qiè hǎo shū rú tóng hé guò qù zuì jié chū de rén tán huà", source: "ルネ・デカルト（仏・哲学者・数学者）", japanese: "すべての良書を読むことは、過去の最も優れた人々と対話するようなものだ。外国語での読書の価値。", english: "Reading all good books is like a conversation with the finest people of past centuries. This is the true value of reading widely in your target language." },
  { number: 159, flag: "🇫🇷", chinese: "人是一根能思想的苇草", pinyin: "rén shì yī gēn néng sī xiǎng de wěi cǎo", source: "ブレーズ・パスカル（仏・数学者・哲学者）", japanese: "人間は考える葦である。弱くても、思考する力によって偉大な学習成果を上げることができる。", english: "Man is but a reed, the weakest in nature, but he is a thinking reed. Even from a position of weakness, thoughtful study can achieve great things." },
  { number: 160, flag: "🇫🇷", chinese: "我们必须把我们的思想建立在坚实的基础上", pinyin: "wǒ men bì xū bǎ wǒ men de sī xiǎng jiàn lì zài jiān shí de jī chǔ shàng", source: "ブレーズ・パスカル（仏・数学者・哲学者）", japanese: "私たちは思考を強固な基礎の上に築かなければならない。語学における基礎文法と基本単語の重要性。", english: "We must build our thoughts on a firm foundation. Master the fundamentals of Chinese grammar and vocabulary before advancing." },
  { number: 161, flag: "🇬🇧", chinese: "知识是一座宝库，而实践就是开启宝库的钥匙", pinyin: "zhī shí shì yī zuò bǎo kù ， ér shí jiàn jiù shì kāi qǐ bǎo kù de yào shi", source: "トーマス・フラー（英・聖職者・作家）", japanese: "知識は宝庫であり、実践はその宝庫を開く鍵である。学んだ単語を実際の会話で使ってみること。", english: "Knowledge is a treasure, and practice is the key to it. Use the vocabulary you learn in real conversation to unlock its full value." },
  { number: 162, flag: "🇬🇧", chinese: "天才就是无止境刻苦勤奋的能力", pinyin: "tiān cái jiù shì wú zhǐ jìng kè kǔ qín fèn de néng lì", source: "トーマス・カーライル（英・歴史家・評論家）", japanese: "天才とは、無限に努力し続ける能力のことである。語学の才能とは、継続できる力そのものである。", english: "Genius is nothing but a great aptitude for patience. True linguistic talent is the ability to keep studying, day after day." },
  { number: 163, flag: "🇷🇺", chinese: "没有任何力量比知识更强大，用知识武装起来的人是不可战胜的", pinyin: "méi yǒu rèn hé lì liàng bǐ zhī shí gèng qiáng dà ， yòng zhī shí wǔ zhuāng qǐ lái de rén shì bù kě zhàn shèng de", source: "マクシム・ゴーリキー（露・文豪）", japanese: "知識より強力な力はない。知識で武装した人間は無敵である。語学力がもたらす自信と強さ。", english: "No force is stronger than knowledge; the person armed with knowledge is invincible. Language ability gives you confidence and strength in any situation." },
  { number: 164, flag: "🇷🇺", chinese: "书籍是人类进步的阶梯", pinyin: "shū jí shì rén lèi jìn bù de jiē tī", source: "マクシム・ゴーリキー（露・文豪）", japanese: "書物は人類進歩の階段である。良質なテキストや本を通じて語学力を高めていくこと。", english: "Books are the ladder of human progress. Let excellent reading materials guide you steadily upward in your Chinese studies." },
  { number: 165, flag: "🇷🇺", chinese: "天才，就其本质而论，只不过是对事业、对工作过程的热爱而已", pinyin: "tiān cái ， jiù qí běn zhì ér lùn ， zhǐ bù guò shì duì shì yè 、 duì gōng zuò guò chéng de rè ài ér yǐ", source: "マクシム・ゴーリキー（露・文豪）", japanese: "天才の本質は、仕事やプロセスに対する愛に過ぎない。語学学習そのものを愛することが上達の近道。", english: "Genius, at its core, is nothing but love for one's work and for the process itself. Love the process of language learning and mastery will follow." },
  { number: 166, flag: "🇷🇺", chinese: "人的天才只是火花，要想使它成熊熊火焰，那就只有学习！学习！", pinyin: "rén de tiān cái zhǐ shì huǒ huā ， yào xiǎng shǐ tā chéng xióng xióng huǒ yàn ， nà jiù zhǐ yǒu xué xí ！ xué xí ！", source: "マクシム・ゴーリキー（露・文豪）", japanese: "人間の才能は火花に過ぎない。それを燃え盛る炎にするには、ただ学ぶことだ！", english: "Human talent is only a spark; to make it a blazing flame, all you need is: study! Study!" },
  { number: 167, flag: "🇩🇪", chinese: "生活就像海洋，只有意志坚强的人，才能到达彼岸", pinyin: "shēng huó jiù xiàng hǎi yáng ， zhǐ yǒu yì zhì jiān qiáng de rén ， cái néng dào dá bǐ àn", source: "カール・マルクス（独・哲学者・経済学者）", japanese: "人生は海のようなものだ。意志の強い者だけが対岸にたどり着ける。語学学習の困難を乗り越える強い意志。", english: "Life is like an ocean; only those with a strong will can reach the other shore. Sustain your determination through every challenge in language learning." },
  { number: 168, flag: "🇩🇪", chinese: "在科学上没有平坦的大道，只有不畏劳苦沿着陡峭山路攀登的人，才有希望达到光辉的顶点", pinyin: "zài kē xué shàng méi yǒu píng tǎn de dà dào ， zhǐ yǒu bù wèi láo kǔ yán zhe dǒu qiào shān lù pān dēng de rén ， cái yǒu xī wàng dá dào guāng huī de dǐng diǎn", source: "カール・マルクス（独・哲学者・経済学者）", japanese: "科学に平坦な道はない。険しい山道を苦労を恐れず登る者だけが、輝かしい頂上に到達できる。", english: "In science, there is no royal road; only those who climb the steep paths of study have any hope of reaching the brilliant summit." },
  { number: 169, flag: "🇩🇪", chinese: "任何时候我也不会满足，越是多读书，就越是深刻地感到不满足，越感到自己知识贫乏", pinyin: "rèn hé shí hòu wǒ yě bú huì mǎn zú ， yuè shì duō dú shū ， jiù yuè shì shēn kè dì gǎn dào bù mǎn zú ， yuè gǎn dào zì jǐ zhī shí pín fá", source: "カール・マルクス（独・哲学者・経済学者）", japanese: "私は決して満足しない。本を読めば読むほど、自分の知識の乏しさを痛感する。常に向上心を持つこと。", english: "I am never satisfied; the more I read, the more deeply I feel my own inadequacy. This humility drives continuous growth in language study." },
  { number: 170, flag: "🇫🇷", chinese: "最困难的时候，也就是离成功不远的时候", pinyin: "zuì kùn nán de shí hòu ， yě jiù shì lí chéng gōng bù yuǎn de shí hòu", source: "ナポレオン・ボナパルト（仏・皇帝）", japanese: "最も困難な時こそ、成功から遠くない時である。学習の壁にぶつかった時こそ、ブレイクスルーの直前である。", english: "The darkest hour is just before the dawn. When language study feels most difficult, a breakthrough is usually close at hand." },
  { number: 171, flag: "🇫🇷", chinese: "不可能只是一个大人物的观点，而不是一个事实", pinyin: "bù kě néng zhǐ shì yí gè dà rén wù de guān diǎn ， ér bú shì yí gè shì shí", source: "ナポレオン・ボナパルト（仏・皇帝）", japanese: "「不可能」とは偉大な人物の意見に過ぎず、事実ではない。語学習得を「不可能」と思わず挑戦すること。", english: "'Impossible' is the word found only in the dictionary of fools. Do not accept 'impossible' when it comes to mastering Chinese." },
  { number: 172, flag: "🇫🇷", chinese: "胜利属于最坚持不懈的人", pinyin: "shèng lì shǔ yú zuì jiān chí bù xiè de rén", source: "ナポレオン・ボナパルト（仏・皇帝）", japanese: "勝利は最も粘り強い者に属する。語学学習においても、最後まで諦めない者が習得できる。", english: "Victory belongs to the most persevering. In language learning, the one who never gives up is the one who achieves fluency." },
  { number: 173, flag: "🇩🇪", chinese: "幻想是诗人的翅膀，假设是科学家的天梯", pinyin: "huàn xiǎng shì shī rén de chì bǎng ， jiǎ shè shì kē xué jiā de tiān tī", source: "ヨハン・ヴォルフガング・フォン・ゲーテ（独・文豪）", japanese: "幻想は詩人の翼であり、仮説は科学者の梯子である。言語学習においても想像力と仮説思考が大切。", english: "Fantasy is the poet's wing; hypothesis is the scientist's ladder. Imagination and systematic thinking are both valuable tools in language learning." },
  { number: 174, flag: "🇩🇪", chinese: "就科学来讲，把前人获得的零星的真理找出来进一步加以发展，就是当之无愧理应受到奖赏的功劳", pinyin: "jiù kē xué lái jiǎng ， bǎ qián rén huò dé de líng xīng de zhēn lǐ zhǎo chū lái jìn yí bù jiā yǐ fā zhǎn ， jiù shì dāng zhī wú kuì lǐ yīng shòu dào jiǎng shǎng de gōng láo", source: "ヨハン・ヴォルフガング・フォン・ゲーテ（独・文豪）", japanese: "先人の知識を発展させることが功績である。既存の辞書や教材を活用して自分の語学力を高めること。", english: "In science, building on the scattered truths discovered by predecessors is meritorious work. Use the dictionaries, textbooks, and knowledge left by those before you." },
  { number: 175, flag: "🇩🇪", chinese: "经验是知识的唯一来源", pinyin: "jīng yàn shì zhī shí de wéi yī lái yuán", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "経験こそが知識の唯一の源である。実際に外国語を使ってコミュニケーションする経験の重要性。", english: "The only source of knowledge is experience. Practicing Chinese in real conversations is irreplaceable." },
  { number: 176, flag: "🇩🇪", chinese: "什么叫疯子，就是重复做同样的事情还期待会出现不同的结果", pinyin: "shén me jiào fēng zi ， jiù shì chóng fù zuò tóng yàng de shì qíng hái qī dài huì chū xiàn bù tóng de jié guǒ", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "狂気とは、同じことを繰り返しながら違う結果を期待することだ。学習方法がうまくいかない時は、やり方を変えるべきだという教え。", english: "Insanity is doing the same thing over and over and expecting different results. If a study method is not working, it is time to change your approach." },
  { number: 177, flag: "🇩🇪", chinese: "并不是我聪明，只是我和问题相处较久", pinyin: "bìng bú shì wǒ cōng míng ， zhǐ shì wǒ hé wèn tí xiāng chǔ jiào jiǔ", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "私が賢いわけではない。ただ、問題と長く付き合っているだけだ。難しい文法や単語も、時間をかければ必ず理解できる。", english: "It is not that I am so smart; it is just that I stay with problems longer. Even the hardest grammar or vocabulary becomes clear if you give it enough time." },
  { number: 178, flag: "🇩🇪", chinese: "知识指的是知道某件事，而智慧则是理解事情的道理，并适当处理的能力", pinyin: "zhī shí zhǐ de shì zhī dào mǒu jiàn shì ， ér zhì huì zé shì lǐ jiě shì qíng de dào lǐ ， bìng shì dàng chǔ lǐ de néng lì", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "知識とは知っていること、知恵とは道理を理解し適切に処理する能力。単語を知っているだけでなく、適切に使えるようになること。", english: "Knowledge is knowing something; wisdom is understanding the principle and being able to apply it appropriately. The goal of study is not just to know words, but to use them well." },
  { number: 179, flag: "🇩🇪", chinese: "科学是非常爱妒忌的，科学只把最高的恩典赐给专心致志地献身于科学的人", pinyin: "kē xué shì fēi cháng ài dù jì de ， kē xué zhǐ bǎ zuì gāo de ēn diǎn cì gěi zhuān xīn zhì zhì dì xiàn shēn yú kē xué de rén", source: "ルートヴィヒ・フォイエルバッハ（独・哲学者）", japanese: "科学は非常に嫉妬深い。専心して身を捧げる者にのみ最高の恩恵を与える。語学も集中して取り組む必要がある。", english: "Science is very jealous and bestows its greatest gifts only on those who devote themselves to it wholeheartedly. Language too rewards total dedication." },
  { number: 180, flag: "🇷🇺", chinese: "科学需要一个人贡献出双重的精力", pinyin: "kē xué xū yào yí gè rén gòng xiàn chū shuāng chóng de jīng lì", source: "イワン・パブロフ（露・生理学者）", japanese: "科学は二重のエネルギーを要求する。語学学習にも多大なエネルギーと情熱が必要である。", english: "Science demands a double contribution of energy from a person. Language learning also requires great energy and sustained passion." },
  { number: 181, flag: "🇬🇧", chinese: "我坚持奋战五十余年，致力于科学的发展。用一个词可以道出我最艰辛的工作特点，这个词就是失败", pinyin: "wǒ jiān chí fèn zhàn wǔ shí yú nián ， zhì lì yú kē xué de fā zhǎn 。 yòng yí gè cí kě yǐ dào chū wǒ zuì jiān xīn de gōng zuò tè diǎn ， zhè ge cí jiù shì shī bài", source: "J.J.トムソン（英・物理学者）", japanese: "私の最も困難な仕事の特徴は「失敗」という言葉で表せる。失敗を重ねながら言語を習得していく過程。", english: "The characteristic of my most difficult work can be summed up in one word: failure. The process of language acquisition is one of repeated attempts and adjustments." },
  { number: 182, flag: "🇯🇵", chinese: "科学的历史，从某种意义上说，就是错觉和失败的历史", pinyin: "kē xué de lì shǐ ， cóng mǒu zhǒng yì yì shàng shuō ， jiù shì cuò jué hé shī bài de lì shǐ", source: "寺田寅彦（日・物理学者・随筆家）", japanese: "科学の歴史は錯覚と失敗の歴史である。語学学習も間違いを繰り返しながら上達していく。", english: "The history of science is, in a sense, the history of illusions and failures. Language learning also advances through mistakes and corrections." },
  { number: 183, flag: "🇷🇺", chinese: "应当热爱科学，因为人类没有什么力量是比科学更强大、更所向无敌的了", pinyin: "yīng dāng rè ài kē xué ， yīn wèi rén lèi méi yǒu shén me lì liàng shì bǐ kē xué gèng qiáng dà 、 gèng suǒ xiàng wú dí de le", source: "マクシム・ゴーリキー（露・文豪）", japanese: "科学（知識）を愛すべきだ。それより強力な力はない。語学力という強力な武器を身につけること。", english: "Love science (knowledge), for no force is mightier or more invincible. Build the powerful tool of language and carry it with you everywhere." },
  { number: 184, flag: "🇷🇺", chinese: "学习永远不晚", pinyin: "xué xí yǒng yuǎn bù wǎn", source: "マクシム・ゴーリキー（露・文豪）", japanese: "学ぶのに遅すぎることはない。何歳からでも新しい言語の学習は始められる。", english: "It is never too late to learn. No matter your age, you can always begin — or deepen — your study of a new language." },
  { number: 185, flag: "🇷🇺", chinese: "人的天才只是火花，要想使它成熊熊火焰，那就只有学习！", pinyin: "rén de tiān cái zhǐ shì huǒ huā ， yào xiǎng shǐ tā chéng xióng xióng huǒ yàn ， nà jiù zhǐ yǒu xué xí ！", source: "マクシム・ゴーリキー（露・文豪）", japanese: "人間の才能は火花に過ぎない。それを燃え盛る炎にするには、ただ学ぶことだ。", english: "Human talent is only a spark; to turn it into a blazing flame, all you need is study." },
  { number: 186, flag: "🇫🇷", chinese: "我思故我在", pinyin: "wǒ sī gù wǒ zài", source: "ルネ・デカルト（仏・哲学者）", japanese: "我思う、故に我在り。自ら考え、理解しながら学習を進めることの重要性。", english: "I think, therefore I am. Active, thoughtful engagement with the material is the essence of meaningful language learning." },
  { number: 187, flag: "🇬🇧", chinese: "科学给人以确实性，也给人以力量", pinyin: "kē xué gěi rén yǐ què shí xìng ， yě gěi rén yǐ lì liàng", source: "ウィリアム・ダンピア（英・探検家・科学者）", japanese: "科学は人に確実性を与え、力を与える。確かな語学力は、コミュニケーションにおける大きな力となる。", english: "Science gives certainty and power. Solid language ability gives you real confidence and strength in communication." },
  { number: 188, flag: "🇬🇧", chinese: "成功的科学家往往是兴趣广泛的人", pinyin: "chéng gōng de kē xué jiā wǎng wǎng shì xìng qù guǎng fàn de rén", source: "ウィリアム・ベヴァリッジ（英・経済学者）", japanese: "成功した科学者は往々にして興味の幅が広い。語学学習においても、多様な分野への興味が語彙力を高める。", english: "Successful scientists often have broad interests. A wide range of interests enriches your vocabulary and makes language learning more dynamic." },
  { number: 189, flag: "🇷🇺", chinese: "科学给青年以营养，给老人以慰藉", pinyin: "kē xué gěi qīng nián yǐ yíng yǎng ， gěi lǎo rén yǐ wèi jiè", source: "ミハイル・ロモノーソフ（露・科学者・詩人）", japanese: "科学（知識）は若者に栄養を与え、老人に慰めを与える。語学学習は生涯にわたって人を豊かにする。", english: "Knowledge nourishes youth and comforts old age. Language learning enriches you at every stage of life." },
  { number: 190, flag: "🇸🇪", chinese: "科学研究的进展及其日益扩充的领域将唤起我们的希望", pinyin: "kē xué yán jiū de jìn zhǎn jí qí rì yì kuò chōng de lǐng yù jiāng huàn qǐ wǒ men de xī wàng", source: "アルフレッド・ノーベル（スウェーデン・発明家）", japanese: "科学研究の進歩は私たちの希望を呼び覚ます。語学学習の進歩も、新たな可能性への希望を与えてくれる。", english: "The progress of scientific research and its ever-expanding domain will awaken our hopes. Every step forward in language learning opens new horizons." },
  { number: 191, flag: "🇷🇺", chinese: "人借助于科学，就可纠正自然界的缺陷", pinyin: "rén jiè zhù yú kē xué ， jiù kě jiū zhèng zì rán jiè de quē xiàn", source: "イリヤ・メチニコフ（露・生物学者）", japanese: "人間は科学（知識）によって自然の欠陥を修正できる。語学力によってコミュニケーションの壁を乗り越えること。", english: "With science (knowledge), humans can correct the flaws of nature. With language ability, we can overcome the barriers of communication." },
  { number: 192, flag: "🇬🇧", chinese: "成功的秘诀在于坚持自己的目标和信念", pinyin: "chéng gōng de mì jué zài yú jiān chí zì jǐ de mù biāo hé xìn niàn", source: "ベンジャミン・ディズレーリ（英・政治家）", japanese: "成功の秘訣は、自分の目標と信念を持ち続けることにある。語学学習の目標を明確に持ち続けること。", english: "The secret of success is constancy to purpose. Set a clear language learning goal and never waver from it." },
  { number: 193, flag: "🇺🇸", chinese: "一个人的成功，不是看他爬得有多高，而是看他跌倒之后能否重新站起来", pinyin: "yí gè rén de chéng gōng ， bú shì kàn tā pá dé yǒu duō gāo ， ér shì kàn tā diē dǎo zhī hòu néng fǒu chóng xīn zhàn qǐ lái", source: "ヴィンス・ロンバルディ（米・コーチ）", japanese: "人の成功は、どれだけ高く登ったかではなく、倒れた後に再び立ち上がれるかで測られる。学習の失敗からの立ち直り。", english: "It is not how high you climb, but how high you bounce when you fall. In language learning, resilience after setbacks is everything." },
  { number: 194, flag: "🇬🇧", chinese: "语言是思想的外衣", pinyin: "yǔ yán shì sī xiǎng de wài yī", source: "サミュエル・ジョンソン（英・文学者）", japanese: "言語は思想の衣服である。豊かな語彙は、豊かな思想を表現する手段となる。", english: "Language is the dress of thought. A rich vocabulary is the means to express a rich inner world." },
  { number: 195, flag: "🇺🇸", chinese: "一个人的成就取决于他如何利用时间", pinyin: "yí gè rén de chéng jiù qǔ jué yú tā rú hé lì yòng shí jiān", source: "ベンジャミン・フランクリン（米・政治家・科学者）", japanese: "人の成就は、時間をどう活用するかにかかっている。語学学習においても、毎日の時間の使い方が重要。", english: "Achievement depends on how one uses one's time. How you spend your study time each day determines your progress." },
  { number: 196, flag: "🇺🇸", chinese: "告诉我，我会忘记；教导我，我可能会记住；让我参与，我才能学会", pinyin: "gào sù wǒ ， wǒ huì wàng jì ； jiào dǎo wǒ ， wǒ kě néng huì jì zhù ； ràng wǒ cān yù ， wǒ cái néng xué huì", source: "ベンジャミン・フランクリン（米・政治家・科学者）", japanese: "話して聞かせても忘れる。教えれば覚えるかもしれない。参加させれば学べる。実践的な語学学習の重要性。", english: "Tell me and I forget; teach me and I may remember; involve me and I learn. Active engagement with Chinese — speaking, writing, listening — is the best way to learn." },
  { number: 197, flag: "🇺🇸", chinese: "投资于知识，回报最丰厚", pinyin: "tóu zī yú zhī shí ， huí bào zuì fēng hòu", source: "ベンジャミン・フランクリン（米・政治家・科学者）", japanese: "知識への投資が最も豊かなリターンをもたらす。語学学習への時間と労力の投資は最高の自己投資である。", english: "An investment in knowledge pays the best interest. Time and effort invested in language study yield the richest rewards." },
  { number: 198, flag: "🇷🇺", chinese: "语言是人类最重要的交际工具", pinyin: "yǔ yán shì rén lèi zuì zhòng yào de jiāo jì gōng jù", source: "ウラジーミル・レーニン（露・政治家）", japanese: "言語は人間の最も重要なコミュニケーションの道具である。語学力の習得が人間関係を豊かにする。", english: "Language is the most important means of human communication. Mastering Chinese opens up relationships and opportunities across the world." },
  { number: 199, flag: "🇩🇪", chinese: "科学是一种强有力的工具。怎样用它，究竟是给人带来幸福还是带来灾难，全取决于人自己，而不取决于工具", pinyin: "kē xué shì yī zhǒng qiáng yǒu lì de gōng jù 。 zěn yàng yòng tā ， jiū jìng shì gěi rén dài lái xìng fú hái shì dài lái zāi nàn ， quán qǔ jué yú rén zì jǐ ， ér bù qǔ jué yú gōng jù", source: "アルベルト・アインシュタイン（独・物理学者）", japanese: "科学は強力な道具である。それをどう使うかは人間次第だ。語学力も使い方次第で人を幸せにも不幸にもできる。", english: "Science is a powerful instrument; whether it brings happiness or disaster depends on how it is used. Language ability, too, depends on how you put it to use." },
  { number: 200, flag: "🇮🇹", chinese: "只有受过教育的人才是自由的", pinyin: "zhǐ yǒu shòu guò jiào yù de rén cái shì zì yóu de", source: "エピクテトス（古代ローマ・哲学者）", japanese: "教育を受けた者だけが自由である。語学力を身につけることで、世界中どこでも自由に生きられる。", english: "Only the educated are truly free. Mastering Chinese gives you the freedom to live, work, and connect anywhere in the world." },
];

const CELLS_PER_LEVEL = 29;
const CHINESE_PER_LEVEL = Math.ceil(CELLS_PER_LEVEL / 2);  // 15
const FOREIGN_PER_LEVEL = Math.floor(CELLS_PER_LEVEL / 2); // 14

export function getQuoteForStamp(stampIndex: number, hskLevel: number = 1): Quote | null {
  if (stampIndex < 1) return null;
  let quoteNumber: number;
  if (stampIndex % 2 === 1) {
    // Odd cells → Chinese quotes (1–100), offset by level
    const chineseIndex = Math.ceil(stampIndex / 2) + (hskLevel - 1) * CHINESE_PER_LEVEL;
    quoteNumber = ((chineseIndex - 1) % 100) + 1;
  } else {
    // Even cells → Foreign quotes (101–200), offset by level
    const foreignIndex = stampIndex / 2 + (hskLevel - 1) * FOREIGN_PER_LEVEL;
    quoteNumber = 100 + ((foreignIndex - 1) % 100) + 1;
  }
  return QUOTES[quoteNumber - 1] ?? null;
}
